nput_ids\\\", \\\"image_input\\\", \\\"image_mask\\\"\\n        \\\"\\\"\\\"\\n        if self.app is not None:\\n\", \"stderr\": \"\", \"return_code\": 0}, \"error\": null, \"metadata\": {\"elapsed_seconds\": 0.45}}"}}}
